def canonical_digest(payload):
    import hashlib
    import json
    blob = json.dumps(payload, sort_keys=True).encode('utf-8')
    return hashlib.sha256(blob).hexdigest()

def wave_energy(wave):
    import numpy as np
    return float(np.sum(np.abs(wave) ** 2))

def task_number(name):
    table = {'vision': 0, 'language': 1, 'action': 2, 'relational': 3}
    return int(table[name])

def directory_listing(path):
    from pathlib import Path
    return sorted((item.name for item in Path(path).iterdir()))

def rotate_wave(wave, angle):
    import numpy as np
    return wave * np.exp(1j * angle)

def conjugate_wave(wave):
    import numpy as np
    return np.conj(wave)

def normalised_wave(wave):
    import numpy as np
    return wave / np.linalg.norm(wave)

def coherence_pair(left, right):
    import numpy as np
    return float(np.real(np.vdot(left, right)))

def unbind_phase(left, right):
    import numpy as np
    return left * np.conj(right)

def batch_mean(values):
    import numpy as np
    return np.mean(values, axis=0)

def stable_softmax(logits):
    import numpy as np
    shifted = logits - np.max(logits)
    weights = np.exp(shifted)
    return weights / np.sum(weights)

def top_index(values):
    best = 0
    for index in range(1, len(values)):
        if values[index] > values[best]:
            best = index
    return int(best)

def hashed_name(name):
    import hashlib
    return hashlib.sha256(str(name).encode('utf-8')).hexdigest()[:16]

def json_roundtrip(payload):
    import json
    return json.loads(json.dumps(payload))

def sorted_digest(body):
    import hashlib
    import json
    blob = json.dumps(body, sort_keys=True).encode('utf-8')
    return hashlib.sha256(blob).hexdigest()

def energy_of(signal):
    import numpy as np
    return float(np.sum(np.abs(signal) ** 2))

def index_of_task(title):
    table = {'vision': 4, 'language': 5, 'action': 6, 'relational': 7}
    return int(table[title])

def files_in(folder):
    from pathlib import Path
    return sorted((item.name for item in Path(folder).iterdir()))

def distinct_caller_count(links):
    step_1 = sorted({edge.source for edge in links})
    return int(len(step_1))

def bounded_length(tokens):
    step_1 = int(len(tokens))
    return max(0.0, min(2.5, float(step_1)))

def bounded_mean(sample):
    step_1 = float(sum(sample) / max(len(sample), 1))
    return max(0.0, min(2.5, float(step_1)))

def bounded_dimension(config):
    step_1 = int(config.dim)
